# Interior is rows 3..9, cols 4..10; exceptional seed at (5,4).
for r in range(3,10):
    for c in range(4,11):
        d=max(abs(r-5), abs(c-4))
        grid[r][c] = 3 if d==0 else (4 if d%2==1 else 2)
assert len(grid)==15 and all(len(row)==15 for row in grid)
print('{"action":"submit","grid":'+__import__('json').dumps(grid,separators=(',',':'))+'}')

